const N = 40;
function ring(y, rad) { const pts = []; for (let i = 0; i <= N; i++) { const a = (i / N) * Math.PI * 2; pts.push([rad * Math.cos(a), y, rad * Math.sin(a)]); } return pts; }
const yB = -h / 2, yT = h / 2;
